 if((m.aid||0)>=2)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.001");
 if((m.aid||0)>0)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.002");
 if((m.support||0)>=2)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.003");
 if((m.support||0)>0)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.004");
 if((m.declines||0)>0)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.005");
 if((m.neutral||0)>0)return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.006");
 return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryLead.007")
