 const last=mem.history?.[mem.history.length-1],summary=[mem.aid?`${mem.aid} aid response${mem.aid===1?'':'s'}`:'',mem.support?`${mem.support} supportive/active response${mem.support===1?'':'s'}`:'',mem.declines?`${mem.declines} refusal${mem.declines===1?'':'s'}`:'',mem.neutral?`${mem.neutral} neutral response${mem.neutral===1?'':'s'}`:''].filter(Boolean).join(' • ');
 return SOSText("hall_staff_correspondence.homeCorrespondenceMemoryHTML.001",mem.exchanges,summary||SOSText("hall_staff_correspondence.homeCorrespondenceMemoryHTML.002"),last?SOSText("hall_staff_correspondence.homeCorrespondenceMemoryHTML.003",last.day,esc(last.result||last.choice)):'')
